mapper.select:
SELECT t.*, e.code AS equipment_code, e.name AS equipment_name, u.nickname AS create_by_name
FROM mes_maintenance t
JOIN mes_equipment e ON e.id = t.equipment_id
LEFT JOIN sys_user u ON u.id = t.create_by

    t.equipment_id = #{equipmentId}
    AND t.type = #{type}
    AND t.status = #{status}

        AND (t.order_no LIKE CONCAT('%', #{keyword}, '%') OR e.code LIKE CONCAT('%', #{keyword}, '%')
             OR e.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY t.id DESC
